Here's a sample end-user API for 3D camera animation in TypeScript:

```typescript
export interface Camera {
  id: string;
  name: string;
  position: Vector3;
  rotation: Quaternion;
}

export interface Animation {
  id: string;
  name: string;
  duration: number;
  cameras: Camera[];
}

export interface AnimationRequest {
  animationId: string;
  startTime: number;
  endTime: number;
}

export interface AnimationResponse {
  animation: Animation;
  frames: Frame[];
}

export interface Frame {
  time: number;
  cameras: Camera[];
}

export interface CameraAnimationService {
  getAnimations(): Promise<Animation[]>;
  getAnimation(animationId: string): Promise<Animation>;
  createAnimation(name: string, duration: number, cameras: Camera[]): Promise<Animation>;
  updateAnimation(animationId: string, name: string, duration: number, cameras: Camera[]): Promise<Animation>;
  deleteAnimation(animationId: string): Promise<void>;
  getAnimationFrames(animationId: string, startTime: number, endTime: number): Promise<Frame[]>;
  startAnimation(animationRequest: AnimationRequest): Promise<void>;
  stopAnimation(animationRequest: AnimationRequest): Promise<void>;
}
```

This API defines interfaces for `Camera`, `Animation`, `AnimationRequest`, `AnimationResponse`, and `Frame`. It also defines a `CameraAnimationService` interface that provides methods for getting animations, creating animations, updating animations, deleting animations, getting animation frames, starting animations, and stopping animations.

Here's a simple example of an End User API for 3D Camera Animation in TypeScript:

```typescript
// camera.ts
import { Vector3 } from 'three';

class Camera {
  private position: Vector3;
  private target: Vector3;
  private up: Vector3;

  constructor(position: Vector3, target: Vector3, up: Vector3) {
    this.position = position;
    this.target = target;
    this.up = up;
  }

  public update() {
    // Update the camera's position and orientation based on the target and up vectors
    this.position.lerp(this.target, 0.1);
    this.rotation.y = Math.atan2(this.up.x, this.up.z);
  }
}

export default Camera;
```

```typescript
// camera-api.ts
import { Camera } from './camera';

class CameraAPI {
  private camera: Camera;

  constructor(camera: Camera) {
    this.camera = camera;
  }

  public update() {
    this.camera.update();
  }
}

export default CameraAPI;
```

```typescript
// main.ts
import { CameraAPI } from './camera-api';

const camera = new Camera(new Vector3(0, 0, -5), new Vector3(0, 0, 0), new Vector3(0, 1, 0));
const cameraAPI = new CameraAPI(camera);

function animate() {
  requestAnimationFrame(animate);
  cameraAPI.update();
}

animate();
```

