function postSlackMessage(text, channel) {
    // Replace 'YOUR_SLACK_API_KEY' with your actual Slack API key
    const apiKey = 'YOUR_SLACK_API_KEY';

    fetch(`https://slack.com/api/chat.postMessage?token=${apiKey}&channel=${channel}&text=${encodeURIComponent(text)}`)
        .then(response => response.json())
        .catch(error => console.error(error));
}
