void loop() {
  if (digitalRead(buttonPin) == HIGH) {
    buttonPressed = true;
  }

  if (buttonPressed) {
    currentLed++;
    if (currentLed > numLeds - 1) {
      currentLed = 0;
    }

    // Fade the LEDs with rainbow colors
    for (int i = 0; i < numLeds; i++) {
      int redValue = (i % 8) * 255 / 8;
      int greenValue = (i % 8) * 255 / 8;
      int blueValue = (i % 8) * 255 / 8;
