#include <FastLED.h>

#define LED_PIN    5
#define NUM_LEDS   60
CRGB leds[NUM_LEDS];

int buttonPin = 2;
bool buttonState = LOW;
unsigned long previousMillis = 0;
const long interval = 300; // milliseconds

void setup() {
  Serial.begin(9600);
  FastLED.addLeds<WS2812B, LED_PIN>(leds, NUM_LEDS);
  pinMode(buttonPin, INPUT);
}

void loop() {
  int i = 0;
  unsigned long currentMillis = millis();

  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;

    if (digitalRead(buttonPin) == HIGH) {
      buttonState = !buttonState;
      i++;

      if (i > NUM_LEDS) {
        i = 0;
      }

      fill_rainbow(leds, NUM_LEDS, i * 64 / NUM_LEDS, 7);
      FastLED.show();
    }
  }
}

void fill_rainbow(CRGB *leds, int count, byte startIndex, byte endIndex) {
  for (byte i = startIndex; i <= endIndex; i++) {
    uint8_t red = 255 - abs(i - startIndex);
    uint8_t green = 255 - abs(i - endIndex);
    uint8_t blue = min(red, green);
    CRGB color = CRGB(red, green, blue);
    for (int j = 0; j < count; j++) {
      leds[j] = color;
    }
  }
}
```

