Here's a C++ program that implements the Fibonacci sequence using a recursive function:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
vector<int> fibonacci(int n, int a, int b) {
    if (n == 0) {
        return vector<int>();
    } else {
        vector<int> result = fibonacci(n - 1, b, a + b);
        result.push_back(a);
        return result;
    }
}

int main() {
    string input;
    int n, a, b;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    // Parse the first two integers
    istringstream iss(input);
    iss >> a >> b;

    if (iss.fail()) {
        throw runtime_error("Invalid input. Please enter two integers.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    if (n < 1) {
        throw runtime_error("Invalid input. Please enter a positive integer.");
    }

    try {
        vector<int> sequence = fibonacci(n, a, b);
        cout << "Fibonacci sequence:";
        for (int i = 0; i < sequence.size(); i++) {
            cout << " " << sequence[i];
        }
        cout << endl;
    } catch (runtime_error& e) {
        cerr << e.what() << endl;
    }

    return 0;
}
