Here's a Swift program that uses regular expressions to identify and replace homophones in a given passage:

```swift
import Foundation

func replaceHomophones(in passage: String) -> String {
    let regex = try! NSRegularExpression(pattern: "\\b(there|their|they're)\\b", options: [])
    let range = NSRange(location: 0, length: passage.utf16.count)

    var correctedPassage = passage

    for match in regex.matches(in: passage, options: [], range: range) {
        let replacement = (match.range.location == 0 ? "there" : "their")
        correctedPassage = (correctedPassage as NSString).replacingCharacters(in: match.range, with: replacement)
    }

    return correctedPassage
}

