import Foundation

func replaceHomophones(in sentence: String) -> String {
    let homophones = [
        "their", "there", "they're"
    ]

    for homophone in homophones {
        sentence = sentence.replacingOccurrences(of: homophone, with: homophone.capitalized)
    }

    return sentence
}

