```javascript
import { NextApiRequest, NextApiResponse } from 'next';
import cors from 'cors';

const corsOptions = {
  origin: ['http://your-wordpress-site.com'], // Replace with your WordPress site URL
  optionsSuccessStatus: 200,
};

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'OPTIONS') {
    await cors(corsOptions)(req, res);
    return;
  }

  res.status(200).json({ message: 'CORS enabled' });
}
```

Replace `http://your-wordpress-site.com` with the actual URL of your WordPress site.

4. In your `next.config.js` file, add the following code to enable the `cors.js` file:

```javascript
module.exports = {
  // ...
  api: {
    bodyParser: false,
    sourceMap: true,
    cors: true,
  },
};
```

