function determineProtocol(inputData) {
  const sourceIP = inputData.sourceIP;
  const destinationIP = inputData.destinationIP;
  const port = inputData.port;
  const payload = inputData.payload;

  // Check if it's an IPv6 address
  const isIPv6 = /^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/.test(sourceIP);

  // Check if it's an HTTP request
  const isHTTP = port === 80 && payload.startsWith("GET ");

  // Check if it's a UDP packet
  const isUDP = port > 1023 && payload.length <= 65535;

  if (isIPv6) {
    return "IPv6";
  } else if (isHTTP) {
    return "HTTP";
  } else if (isUDP) {
    return "UDP";
  } else {
    return "Unknown";
  }
