const NestFactory = require('@nestjs/core');
const { TypeOrmModule } = require '@nestjs/typeorm';
const { Permission } = require('./permission.entity');
const { UserRole } = require('./user-role.entity');
const { AuthGuard } = require('./auth.guard');
const { RoleGuard } = require('./role.guard');

async function bootstrap() {
  const app = await NestFactory.create(NestFactory);

  app.useGlobalGuards(new AuthGuard(), new RoleGuard());

  app.useModule(TypeOrmModule.forRoot({
    type: 'mysql',
    host: 'localhost',
    port: 3306,
    username: 'root',
    password: 'password',
    database: 'your_database',
    entities: [__dirname + '/**/*.entity{.ts,.js}'],
    synchronize: true,
  }));

  app.useModule(TypeOrmModule.forFeature([Permission, UserRole]));

  await app.listen(3000);
}

bootstrap();
```

