Here's a React Hooks-based component that converts temperatures between Celsius, Fahrenheit, and Kelvin:

```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const handleConvert = () => {
    switch (unit) {
      case 'celsius':
        setTemperature((temperature * 1.8) + 32);
        setUnit('fahrenheit');
        break;
      case 'fahrenheit':
        setTemperature((temperature - 32) / 1.8);
        setUnit('celsius');
        break;
      case 'kelvin':
        setTemperature(temperature - 273.15);
        setUnit('celsius');
        break;
      default:
        break;
    }
  };

  return (
    <div>
      <h2>Temperature Converter</h2>
      <label htmlFor="temperature">Enter a temperature:</label>
      <input type="number" id="temperature" value={temperature} onChange={e => setTemperature(parseFloat(e.target.value))} />
      <button onClick={handleConvert}>Convert</button>
      <p>Result: {temperature} {unit}</p>
    </div>
  );
};

export default TemperatureConverter;
```

Here's a React hook that allows you to convert temperatures between Celsius, Fahrenheit, and Kelvin:

```javascript
import { useState } from 'react';

const useTemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const convertTemperature = (newTemperature, newUnit) => {
    switch (newUnit) {
      case 'celsius':
        return (newTemperature * 9 / 5) + 32;
      case 'fahrenheit':
        return (newTemperature - 32) * 5 / 9;
      case 'kelvin':
        return newTemperature + 273.15;
      default:
        return newTemperature;
    }
  };

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  const getConvertedTemperature = () => {
    const newTemperature = convertTemperature(temperature, unit);
    return parseFloat(newTemperature.toFixed(2));
  };

  return { temperature, unit, handleInputChange, handleUnitChange, getConvertedTemperature };
};

export default useTemperatureConverter;
```

