```javascript
import React, { useState } from 'react';

function useTemperatureConverter() {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('C');

  function handleConvert(event) {
    event.preventDefault();

    const newTemperature = (unit === 'C') ? (temperature * 9 / 5) + 32 : (temperature - 32) * 5 / 9;
    setTemperature(newTemperature);
    setUnit((unit === 'C') ? 'F' : 'C');
  }

  return { temperature, unit, handleConvert };
}

function TemperatureConverter() {
  const { temperature, unit, handleConvert } = useTemperatureConverter();

  return (
    <div>
      <h1>Temperature Converter</h1>
      <form onSubmit={handleConvert}>
        <label htmlFor="temperature">Temperature:</label>
        <input type="number" id="temperature" value={temperature} onChange={(e) => setTemperature(parseFloat(e.target.value))} />
        <label htmlFor="unit">Unit:</label>
        <select id="unit" value={unit} onChange={(e) => setUnit(e.target.value)}>
          <option value="C">Celsius</option>
          <option value="F">Fahrenheit</option>
        </select>
        <button type="submit">Convert</button>
      </form>
      <p>Result: {temperature} {unit}</p>
    </div>
  );
}

export default TemperatureConverter;
