  return (
    <div>
      <h1>{temperature}°{unit}</h1>
      <button onClick={handleConvert}>Convert</button>
    </div>
  );
};

export default TemperatureConverter;
```

Here's a simple React component using the useEffect hook to convert between different temperature units:

```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  useEffect(() => {
    if (unit === 'celsius') {
      const fahrenheit = (temperature * 9 / 5) + 32;
      setTemperature(fahrenheit);
    } else {
      const celsius = (temperature - 32) * 5 / 9;
      setTemperature(celsius);
    }
  }, [unit, temperature]);

  const handleUnitChange = (e) => {
    setUnit(e.target.value);
  };

  return (
    <div>
      <label htmlFor="temperature">Temperature:</label>
      <input type="number" id="temperature" value={temperature} onChange={(e) => setTemperature(e.target.value)} />
      <label htmlFor="unit">Unit:</label>
      <select id="unit" value={unit} onChange={handleUnitChange}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
      </select>
      <p>Result: {temperature} {unit}</p>
    </div>
  );
};

export default TemperatureConverter;
```

