Here's a Go program that takes the name of the Go source file and the name of the struct as input, parses the struct, and generates an Avro schema for it. The generated schema is saved in a file named "struct.avsc".

```go
package main

import (
	"fmt"
	"io/ioutil"
	"log"
	"reflect"
	"strings"

	"github.com/apache/avro/v2/avro"
)

func main() {
	sourceFile := "path/to/your/go/source/file.go"
	structName := "YourStructName"

	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		log.Fatal(err)
	}

	tokens := strings.Split(string(content), "\n")

	var schema *avro.Schema
	for _, token := range tokens {
		if strings.HasPrefix(token, "type ") {
			parts := strings.SplitN(token, " ", 2)
			if len(parts) == 2 {
				schema = &avro.Schema{
					Name: parts[1],
				}
				break
			}
		}
	}

	if schema == nil {
		log.Fatalf("Unable to find the struct definition in the source file.")
	}

	fields := []avro.Field{}
	for fieldName := range reflect.TypeOf(schema.Value).Fields() {
		field := reflect.FieldValue(schema.Value, fieldName)
		if field.CanInterface() {
			fields = append(fields, avro.Field{
				Name:  fieldName,
				Type:  avro.Type_STRING,
				Default: field.Interface().(string),
			})
		} else {
			log.Fatalf("Unable to convert the field value to a string.")
		}
	}

	schema.Fields = fields

	err = ioutil.

