Here's a Go program that parses a struct in a Go source file and generates a Avro schema from it:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"reflect"
	"strings"
)

type StructInfo struct {
	Name     string
	Fields   []FieldInfo
}

type FieldInfo struct {
	Name    string
	Type    string
	Nullable bool
}

func parseStruct(file string, structName string) (StructInfo, error) {
	content, err := ioutil.ReadFile(file)
	if err != nil {
		return StructInfo{}, fmt.Errorf("error reading file: %w", err)
	}

	tokens := strings.Split(string(content), "\n")
	for _, token := range tokens {
		if strings.HasPrefix(token, "type ") {
			structType := strings.TrimSpace(token[len("type "):])
			if structType == structName {
				fields := make([]FieldInfo, 0)

				for _, field := range reflect.TypeOf(reflect.New(structName)).Field() {
					fieldType := field.Type.String()
					nullable := field.Tag.Get("json") == "omitempty"

					fields = append(fields, FieldInfo{
						Name:    field.Name,
						Type:    fieldType,
						Nullable: nullable,
					})
				}

				return StructInfo{
					Name:     structName,
					Fields:   fields,
				}, nil
			}
		}
	}

	return StructInfo{}, fmt.Errorf("structure not found in file")
}

