	if err != nil {
		fmt.Println(err)
		return
	}

	// Extract the struct definition from the Go code
	structDef, err := extractStructDef(string(content), structName)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Generate the Avro schema
	schemaDef, err := generateAvroSchema(structDef)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Write the Avro schema to a file
	err = os.WriteFile("struct.avsc", []byte(schemaDef), 0644)
	if err != nil {
		fmt.Println(err)
		return
	}
}

