<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Display Background Image</title>
    <style>
        body {
            text-align: center;
        }
        button {
            padding: 10px 20px;
            background-color: #4CAF50;
            color: white;
            cursor: pointer;
        }
        button:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>
    <button onclick="displayBackgroundImage()">Display Background Image</button>
    <script>
        function displayBackgroundImage() {
            const img = document.createElement('img');
            img.src = chrome.runtime.getURL('/background.png');
            img.alt = 'Background Image';
            img.style.position = 'absolute';
            img.style.top = '0';
            img.style.left = '0';
            img.style.width = '100%';
            img.style.height = '100%';
            img.style.objectFit = 'cover';
            img.style.zIndex = '-1';
            document.body.appendChild(img);
        }
    </script>
</body>
</html>
```

