</head>
<body>
    <h1>Display Background Image</h1>
    <button onclick="displayBackgroundImage()">Display Background Image</button>

    <script>
        function displayBackgroundImage() {
            chrome.tabs.query({active: true, currentWindow: true}, tabs => {
                chrome.tabs.executeScript(tabs[0].id, {file: 'background_image.js'});
            });
        }
    </script>
</body>
</html>
