function prefixString(string, prefix) {
  return `${prefix}${string}`;
}

const myString = "example";
const regexPattern = /^my/;
const prefixedString = prefixString(myString, 'my');
const match = regexPattern.test(prefixedString);

console.log(match); // Output: true
```

