Here are the steps to create your desired React application:

1. Create a new React project:
```bash
npx create-react-app template-responses-app
cd template-responses-app
```
2. Install necessary dependencies:
```bash
npm install axios react-dropdown
```
3. Update `App.js` to fetch the template from the API and display the response form:
```javascript
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Dropdown from 'react-dropdown';

function App() {
  const [template, setTemplate] = useState(null);
  const [response, setResponse] = useState({});

  useEffect(() => {
    async function fetchTemplate() {
      try {
        const response = await axios.get('http://localhost:8080/template');
        setTemplate(response.data);
      } catch (error) {
        console.error(error);
      }
    }

    fetchTemplate();
  }, []);

  if (!template) {
    return <div>Loading...</div>;
  }

  const handleChoiceChange = (event, choice) => {
    setResponse({ ...response, [choice]: event.value });
  };

  const handleSubmit = () => {
    axios.post('http://localhost:8080/response', response)
      .then(response => console.log('Response submitted successfully:', response))
      .catch(error => console.error('Error submitting response:', error));
  };

  return (
    <div className="App">
      {template && (
        <div>
          <h1>{template.sentence}</h1>
          <Dropdown
            value={response.choices.relevance}
            onChange={e => handleChoiceChange(e, 'relevance')}
            options={template.choices.relevance}
          />
          <Dropdown
            value={response.choices.quantity}
            onChange={e => handleChoiceChange(e, 'quantity')}
            options={template.choices.quantity}

