% Define the population size and initial gene frequencies
population_size = 100;
gene_freq_A = 0.5; % Frequency of the advantageous gene A
gene_freq_B = 0.5; % Frequency of the disadvantageous gene B

% Initialize the population
population = zeros(population_size, 1);
for i = 1:population_size
