        population(i) = 'A';
    else
        population(i) = 'B';
    end
end

% Simulate natural selection over multiple generations
num_generations = 100;
for generation = 1:num_generations
    % Calculate the fitness of each individual based on the gene frequency
    fitness = gene_freq_A * 100 + gene_freq_B * (-5);

    % Select individuals for reproduction based on their fitness
    selected_individuals = topk(fitness, population_size);

    % Create offspring by randomly selecting parents from the selected individuals
