        parent_A = selected_individuals(randi([1, numel(selected_individuals)]));
        parent_B = selected_individuals(randi([1, numel(selected_individuals)]));
        offspring(i) = 'A'; % Assume the advantageous gene is dominant
    end

    % Update the population for the next generation
    population = offspring;

    % Update the gene frequencies based on the new population
    gene_freq_A = sum(population == 'A') / population_size;
    gene_freq_B = sum(population == 'B') / population_size;
end

% Plot the change in gene frequencies over time
plot(generation, gene_freq_A, generation, gene_freq_B);
xlabel('Generation');
ylabel('Gene Frequency');
title('Natural Selection Simulation');
