import argparse
import boto3
from botocore.exceptions import ClientError

def get_failed_workflows(client):
    try:
        response = client.list_workflows(
            MaxResults=10,
            StateFilter='FAILED'
        )
        return response['Workflows']
    except ClientError as error:
        print(error)
        return None

def retrieve_inputs_and_names(workflows):
    inputs_and_names = []
    for workflow in workflows:
        try:
            response = client.get_workflow(
                WorkflowId=workflow['WorkflowId']
            )
            inputs_and_names.append({
                'Name': workflow['Name'],
                'Inputs': response['Inputs']
            })
        except ClientError as error:
            print(error)
    return inputs_and_names

def re_execute_workflows(client, inputs_and_names):
    for name, inputs in inputs_and_names:
        retry_name = f"{name} (Retry)"
        try:
            response = client.start_workflow(
                WorkflowId=workflow['WorkflowId'],
                Inputs=inputs,
                Name=retry_name
            )
            print(f"Retrying {name}: {response['WorkflowExecutionId']}")
        except ClientError as error:
            print(error)

