Here's a simple example of a toast notification using React Context:

1. Create a `ToastContext.js` file:
```javascript
import { createContext, useState } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = useState(null);

  function showToast(message) {
    setToast({ message, duration: 3000 });
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Create a `Toast.js` file:
```javascript
import React from 'react';
import { useContext } from 'react';

function Toast() {
  const { toast } = useContext(ToastContext);

  if (!toast) {
    return null;
  }

  return (
    <div className="toast">
      <p>{toast.message}</p>
      <button onClick={() => setToast(null)}>Close</button>
    </div>
  );
}

export default Toast;
```

3. Use the `ToastProvider` and `Toast` components in your app:
```javascript
import React from 'react';
import { ToastProvider, Toast } from './components';

function App() {
  return (
    <ToastProvider>
      <Toast />
      <button onClick={() => showToast('Hello, world!')}>Show toast</button>
    </ToastProvider>
  );
}

export default App;
```

