    itemToString: (item) => item.email,
    onSelect: (item) => setSelectedEmail(item),
    onInputValueChange: searchEmails,
  });

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} />
      <ul {...getMenuProps()}>
        {isOpen &&
