```csharp
using System;
using System.IO;
using System.Linq;
using Accord.MachineLearning;
using Accord.MachineLearning.Text;
using Accord.Statistics;

namespace TextClassification
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the dataset
            var dataset = new[]
            {
                new { Sentence = "The sports game was exciting.", Label = "Sports" },
                new { Sentence = "The political rally was heated.", Label = "Politics" },
                new { Sentence = "The entertainment show was amazing.", Label = "Entertainment" }
            };

            // Create a Naive Bayes classifier
            var classifier = new NaiveBayes();

            // Train the classifier
            classifier.Train(dataset);

            // Predict the labels of new observations
            var newObservations = new[]
            {
                new { Sentence = "The sports game was exciting." },
                new { Sentence = "The political rally was heated." },
                new { Sentence = "The entertainment show was amazing." }
            };

            var predictions = classifier.Predict(newObservations);

            // Print the predictions
            foreach (var prediction in predictions)
            {
                Console.WriteLine($"{prediction.Sentence} - Predicted label: {prediction.Label}");
            }
        }
    }
}
```

