type Dataset = {
  label: string;
  value: number;
};

function generateBarChart(dataset: Dataset[]): void {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  canvas.width = 800;
  canvas.height = 400;

  const bars = dataset.map((data) => {
    const barWidth = 30;
