    const barY = 400 - barHeight;

    ctx.fillStyle = 'blue';
    ctx.fillRect(barX, barY, barWidth, barHeight);

    ctx.font = '16px Arial';
    ctx.fillStyle = 'white';
    ctx.fillText(data.label, barX, barY - 20);
  });

  document.body.appendChild(canvas);
}

