```

Here's a simple TypeScript program that generates a bar chart from a user-inputted dataset:

```typescript
class BarChart {
  private data: number[];

  constructor(data: number[]) {
    this.data = data;
  }

  generateChart() {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    canvas.width = 400;
    canvas.height = 300;

    const barWidth = 20;
    const barHeight = 50;
    const gap = 5;

    let x = 0;
    let y = 0;

    for (const value of this.data) {
      ctx.fillRect(x, y, barWidth, barHeight);
      x += barWidth + gap;
    }

    return canvas;
  }
}

