To prevent your planets from being too close together, you can implement a simple spatial partitioning algorithm like a grid or a quadtree. This will allow you to quickly check if a new planet is too close to an existing one before adding it to the scene.

Here's a simple example using a grid:

1. Create a 2D grid with a cell size equal to the minimum distance between planets.
2. Assign each planet to a grid cell based on its position.
3. When generating a new planet, check if its position falls within any of the occupied grid cells. If so, reject the planet and generate a new one until it is not too close to any other planet.

You can implement this algorithm in your `generateRandomPlanets` function by adding the following steps:

```javascript
const gridWidth = 10;
const gridHeight = 10;
const cellSize = 35;

let grid = [];

for (let y = 0; y < gridHeight; y++) {
  grid[y] = [];
  for (let x = 0; x < gridWidth; x++) {
    grid[y][x] = false;
  }
}

function isInGrid(position) {
  const x = Math.floor(position[0] / cellSize);
  const y = Math.floor(position[1] / cellSize);
  return x >= 0 && x < gridWidth && y >= 0 && y < gridHeight;
}

function isTooClose(position, grid) {
  const x = Math.floor(position[0] / cellSize);
  const y = Math.floor(position[1] / cellSize);

  for (let i = y - 1; i <= y + 1; i++) {
    for (let j = x - 1; j <= x + 1; j++) {
      if (i >= 0 && i < gridHeight && j >= 0 && j < gridWidth && !grid[i][j]) {
        continue;
      }

      const distance = Math.sqrt((position[0] - grid[i][j][0]) ** 2 + (position[1] - grid[i][j][1]) ** 2);

