const { promisify } = require('util');
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.client = new Redis();

    this.client.on('error', (err) => {
      console.error('Error with Redis:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error('Error checking Redis connection:', err);
      return false;
    }
  }

  async get(key) {
    const value = await promisify(this.client.get)(key);
    return value;
  }

  async set(key, value, duration) {
    await promisify(this.client.set)(key, value, 'EX', duration);
  }

  async del(key) {
    await promisify(this.client.del)(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

