Here's a Go code that uses a table of specific negative words to identify if a given sentence contains a double negative:

```go
package main

import (
	"fmt"
	"strings"
)

var negativeWords = []string{"no", "not", "never", "nothing", "none"}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	words := strings.Split(sentence, " ")

	for _, word := range words {
		if containsNegativeWord(word) {
			if containsDoubleNegation(sentence, word) {
				fmt.Println("The sentence contains a double negative.")
			}
		}
	}
}

func containsNegativeWord(word string) bool {
	for _, negWord := range negativeWords {
		if word == negWord || word == "not" + negWord {
			return true
		}
	}
	return false
}

func containsDoubleNegation(sentence string, word string) bool {
	return strings.Contains(sentence, "not") && strings.Contains(sentence, word)
}
```

