# Define the function to check if an SID is present in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher("DC=$domain")
    $searcher.Filter = "(&(objectClass=user)(objectCategory=person)(sAMAccountName=*))"
    $searcher.PropertiesToLoad.Add("sIDHistory")
    $results = $searcher.FindAll()

    foreach ($result in $results) {
        $sidHistory = $result.sIDHistory
        if ($sidHistory -contains $sid) {
            return $true
        }
    }

    return $false
}

# Define the function to recursively check folders for SIDs in SIDHistory
function CheckFoldersForSIDHistory($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        $sidHistorySids = @()

        foreach ($access in $acl.Access) {
            if ($access.IdentityReference -is [System.Security.Principal.SecurityIdentifier]) {
                $sid = $access.IdentityReference.Value
                if (CheckSIDInSIDHistory($sid)) {
                    $sidHistorySids += $sid
                }
            }
        }

        if ($sidHistorySids.Count -gt 0) {
            Write-Host "Folder: $($_.FullName)"
            Write-Host "SIDs in SIDHistory: $sidHistorySids"
        }

        CheckFoldersForSIDHistory($_.FullName)
    }
}

# Call the function to start the search
CheckFoldersForSIDHistory("C:\path\to\starting\folder")
